local key = KEYS[1]

local limit = tonumber(ARGV[1])
local windowMs = tonumber(ARGV[2])
local requestId = ARGV[3]

-- Validate inputs
if not limit or limit < 1 or limit % 1 ~= 0
or not windowMs or windowMs < 1 or windowMs % 1 ~= 0
or not requestId or requestId == "" then
	return redis.error_reply("Invalid rate limit arguments")
end

-- Get current time from Redis in milliseconds
local time = redis.call("TIME")

local now =
	tonumber(time[1]) * 1000 +
	math.floor(tonumber(time[2]) / 1000)

-- Calculate the sliding window boundary
local cutoff = now - windowMs

-- Remove expired requests
redis.call("ZREMRANGEBYSCORE", key, "-inf", cutoff)

-- Count active requests
local count = redis.call("ZCARD", key)

-- Reject if the limit has been reached
if count >= limit then

-- Get the oldest active request
	local oldest = redis.call(
		"ZRANGE", key, 0, 0, "WITHSCORES"
	)

	local oldestTimestamp = tonumber(oldest[2])

	-- Calculate when the next slot becomes available
	local retryAfterMs =
		math.max(1, oldestTimestamp + windowMs - now)

	return {0, 0, retryAfterMs}
end

-- Record the new request
redis.call("ZADD", key, now, requestId)

-- Expire the key after inactivity
redis.call("PEXPIRE", key, windowMs)

-- Return allowed, remaining requests, retry time
return {1, limit - count - 1, 0}